CREATE TABLE IF NOT EXISTS table_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_code TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, phone TEXT NOT NULL, zone TEXT NOT NULL, fulfillment TEXT NOT NULL, slot TEXT NOT NULL, payment_method TEXT NOT NULL, items JSONB NOT NULL, subtotal NUMERIC(10,2) NOT NULL, discount NUMERIC(10,2) NOT NULL DEFAULT 0, delivery_fee NUMERIC(10,2) NOT NULL DEFAULT 0, packaging_fee NUMERIC(10,2) NOT NULL DEFAULT 20, gst NUMERIC(10,2) NOT NULL, grand_total NUMERIC(10,2) NOT NULL, status TEXT NOT NULL DEFAULT 'confirmed', kitchen_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())